import{createStudy,seededRandom,downloadSVG}from'./core.js';
const study=createStudy({id:18,title:'Ghost in the Grid',category:'Layout / Content',accent:'#cfef4c',background:'#181e16',foreground:'#eef2df'}),grid=document.querySelector('#ghost-grid'),dialog=document.querySelector('#ghost-viewer');
const names=['Counterpoint','A softer system','Radial memory','Field notes','A line becomes a place','The intervals','Orbit, interrupted','Soft architecture','Nothing stays put','Another point of view','Possible arrangements','A familiar stranger'];
const colors=[['#cfef4c','#263a17'],['#f39c7c','#3a292a'],['#c8baf0','#423959'],['#e6e5cf','#344232'],['#284b4c','#b1dbc7'],['#a6c3ac','#213b31']];
let items=names.map((name,i)=>({id:i+1,name,kind:['linear','organic','radial'][i%3],seed:i+17})),filter='all',reversed=false,selected=null,opener=null;const animations=new Set(),flying=new Set();
function svg(item){const random=seededRandom(item.seed),kind=item.kind;let inside='';if(kind==='linear'){for(let i=0;i<14;i++)inside+=`<path d="M${20+i*12} 20 Q${55+random()*100} 110 ${20+i*12} 200" fill="none" stroke="currentColor" stroke-width="${i%4===0?3:1}"/>`}else if(kind==='organic'){for(let i=0;i<12;i++)inside+=`<ellipse cx="110" cy="${56+random()*25}" rx="${13+random()*14}" ry="${44+random()*27}" fill="currentColor" fill-opacity=".24" stroke="currentColor" stroke-width=".7" transform="rotate(${i*30} 110 110)"/>`}else{for(let i=0;i<22;i++)inside+=`<ellipse cx="110" cy="110" rx="${78+random()*10}" ry="${19+random()*20}" fill="none" stroke="currentColor" stroke-width="1" transform="rotate(${i*180/22} 110 110)"/>`}return`<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 220 220" aria-hidden="true">${inside}</svg>`}
function palette(item,node){const [bg,fg]=colors[(item.id-1)%colors.length];node.style.setProperty('--card-bg',bg);node.style.setProperty('--card-fg',fg)}
function runAnimation(node,frames,options){if(!study.running())return null;const animation=node.animate(frames,options);animations.add(animation);animation.finished.then(()=>animations.delete(animation)).catch(()=>animations.delete(animation));return animation}
function settle(){for(const a of animations)a.cancel();animations.clear();for(const node of flying)node.remove();flying.clear()}
function render(){const before=new Map([...grid.children].map(node=>[+node.dataset.id,node.getBoundingClientRect()]));const live=new Map([...grid.children].map(node=>[+node.dataset.id,node]));for(const node of grid.children)node.getAnimations().forEach(a=>a.cancel());let visible=items.filter(item=>filter==='all'||item.kind===filter);if(reversed)visible=visible.slice().reverse();const remaining=new Set(visible.map(item=>item.id));for(const[id,node]of live){if(!remaining.has(id)&&study.running()){const box=before.get(id)||node.getBoundingClientRect(),clone=node.cloneNode(true);clone.classList.add('ghost-flying');clone.inert=true;clone.setAttribute('aria-hidden','true');Object.assign(clone.style,{left:box.left+'px',top:box.top+'px',width:box.width+'px',height:box.height+'px'});document.body.append(clone);flying.add(clone);const exit=runAnimation(clone,[{opacity:1,transform:'scale(1)'},{opacity:0,transform:'scale(.88)'}],{duration:240,easing:'ease-out'});exit?.finished.finally(()=>{clone.remove();flying.delete(clone)}).catch(()=>{})}if(!remaining.has(id))node.remove()}
  for(const item of visible){let node=live.get(item.id);if(!node){node=document.createElement('button');node.type='button';node.className='ghost-card';node.dataset.id=item.id;node.innerHTML=`<div class="form-art"><span class="form-index">FORM ${String(item.id).padStart(3,'0')}</span>${svg(item)}<span class="form-plus">↗</span></div><div class="form-title"><strong></strong><small>${item.kind}</small></div>`;palette(item,node)}node.classList.toggle('wide',item.id%5===1||item.name.length>25);node.querySelector('strong').textContent=item.name;node.setAttribute('aria-label','Inspect '+item.name);grid.append(node)}
  for(const node of grid.children){const id=+node.dataset.id,old=before.get(id),after=node.getBoundingClientRect();node.getAnimations().forEach(a=>a.cancel());if(old){const x=old.left-after.left,y=old.top-after.top,sx=old.width/after.width,sy=old.height/after.height;if(Math.abs(x)+Math.abs(y)>1||Math.abs(sx-1)>.02)runAnimation(node,[{transform:`translate(${x}px,${y}px) scale(${sx},${sy})`,transformOrigin:'0 0'},{transform:'none',transformOrigin:'0 0'}],{duration:650,easing:'cubic-bezier(.22,1,.36,1)'})}else runAnimation(node,[{opacity:0,transform:'translateY(20px) scale(.94)'},{opacity:1,transform:'none'}],{duration:420,easing:'cubic-bezier(.22,1,.36,1)'})}
  document.querySelector('#ghost-status').textContent=visible.length+' forms. Every change creates a new composition.';document.querySelectorAll('[data-filter]').forEach(button=>button.setAttribute('aria-pressed',String(button.dataset.filter===filter)))}
document.querySelectorAll('[data-filter]').forEach(button=>button.addEventListener('click',()=>{filter=button.dataset.filter;render()}));document.querySelector('#ghost-order').addEventListener('click',()=>{reversed=!reversed;render()});document.querySelector('#ghost-add').addEventListener('click',()=>{if(items.length>=24){study.notify('Twenty-four forms is enough room to play. Reset to start over.');return}const id=items.length+1;items.push({id,name:'An unexpected guest '+id,kind:['linear','organic','radial'][id%3],seed:id+35});filter='all';render()});grid.addEventListener('click',event=>{const button=event.target.closest('[data-id]');if(!button)return;selected=items.find(item=>item.id===+button.dataset.id);opener=button;document.querySelector('#ghost-title').textContent=selected.name;document.querySelector('#ghost-caption').value=selected.name;const large=document.querySelector('#ghost-large');large.innerHTML=svg(selected);palette(selected,large);dialog.showModal()});document.querySelector('#ghost-close').addEventListener('click',()=>dialog.close());dialog.addEventListener('close',()=>opener?.focus({preventScroll:true}));document.querySelector('#ghost-rename').addEventListener('click',()=>{const text=document.querySelector('#ghost-caption').value.trim();if(!text){study.notify('Give the form a name first.');return}selected.name=text;render();dialog.close()});study.onMotion(run=>{if(!run)settle()});study.setReset(()=>{settle();selected=null;opener=null;items=names.map((name,i)=>({id:i+1,name,kind:['linear','organic','radial'][i%3],seed:i+17}));filter='all';reversed=false;render()});study.setExport(()=>{const item=selected||items[0];const holder=document.createElement('div');holder.innerHTML=svg(item);const el=holder.firstElementChild;const [bg,fg]=colors[(item.id-1)%colors.length];el.style.color=fg;el.style.background=bg;downloadSVG(el,'sub-grid-form-'+item.id+'.svg',{background:bg})});study.cleanup(settle);render();
